from pathlib import Path
import json,hashlib,sqlite3
import numpy as np,pandas as pd
from scipy.optimize import linprog
from scipy.sparse import csr_matrix,eye,hstack,vstack
p=Path(__file__).parent;out=p/'results';m=json.load(open(p/'stage/manifest.json'));F=m['files'];T=[f'{e}_pIC50_direct_inhibition' for e in ['CYP1A2','CYP2C9','CYP2D6','CYP3A4']];truth=pd.read_csv(F['official_train']['path']).set_index('Molecule_Name');q=pd.read_csv(F['official_blind']['path']);coef=json.load(open(out/'COEFFICIENTS.json'));weights=np.array([coef['weights'][t] for t in T]);assert weights.min()>=0 and weights.max()<=1;N=pd.read_csv(F['original_full_OOF']['path']).set_index('Molecule_Name').loc[truth.index,T].to_numpy();H=pd.read_csv(F['H6_feature_full_OOF']['path']).set_index('Molecule_Name').loc[truth.index,T].to_numpy();errors=[]
for j,t in enumerate(T):
 mask=truth[t].notna().to_numpy();base=N[mask,j];extra=H[mask,j];d=extra-base;lo=truth[t+'_conf_low'].to_numpy()[mask];hi=truth[t+'_conf_high'].to_numpy()[mask];n=len(base);A=vstack([hstack([-csr_matrix(d[:,None]),-eye(n)]),hstack([csr_matrix(d[:,None]),-eye(n)])],format='csr');r=linprog(np.r_[0.,np.ones(n)/n],A_ub=A,b_ub=np.r_[base-lo,hi-base],bounds=[(0,1)]+[(0,None)]*n,method='highs');assert r.success;pred=base+weights[j]*d;loss=abs(pred-np.clip(pred,lo,hi)).mean();errors.append(abs(loss-r.fun));assert errors[-1]<1e-8 and n==coef['observed_label_counts'][t]
ids=q.Molecule_Name.tolist();native=pd.read_csv(F['blind750_original_raw']['path']).set_index('Molecule_Name').loc[ids,T].to_numpy();heads=np.column_stack([np.load(F['head_'+t]['path'],allow_pickle=False) for t in T]);raw=(1-weights)*native+weights*heads;op=next(x for x in json.load(open(F['original_operator']['path'])) if x['context']=='blind750');mu=np.array(op['original_raw_reference_mean']);mapped=np.column_stack([np.maximum((raw[:,j]-mu[j])*op['calibration'][t.split('_')[0]]['scale']+mu[j]+op['calibration'][t.split('_')[0]]['offset'],op['floor']) for j,t in enumerate(T)]);checks={}
for lane,expected in [('raw',raw),('served',mapped)]:
 file=out/f'incumbent-anchored-H6-{lane}-PRIVATE.csv';d=pd.read_csv(file);assert d.Molecule_Name.tolist()==ids and d.SMILES.tolist()==q.SMILES.tolist() and d.Molecule_Name.is_unique;values=d[T].to_numpy();error=float(abs(values-expected).max());assert error<1e-12 and np.isfinite(values).all() and (values.std(0,ddof=1)>=.01).all();checks[lane]={'sha256':hashlib.sha256(file.read_bytes()).hexdigest(),'max_reconstruction_error':error,'sample_std':values.std(0,ddof=1).tolist()}
control=out/'lambda0-original-incumbent-CONTROL.csv';best='349165ecf50906e43a27f12dee97891a92cda59e798db614ef27a7c920c38a37';assert hashlib.sha256(control.read_bytes()).hexdigest()==best==hashlib.sha256(Path(F['blind750_original_served']['source']).read_bytes()).hexdigest();zero=json.load(open(out/'LAMBDA0_CONTROL.json'));assert zero['numeric_operator_max_abs_error']<1e-12 and zero['no_per_row_corrections'];con=sqlite3.connect('file:/Users/adeliyaleleytner/.cache/cyp-inhibition/orx-store/orx.db?mode=ro',uri=True);status,source=con.execute('select status,commit_sha from runs where id=?',('ea18ec6c-3611-452b-bd03-fb4a9ec3edee',)).fetchone();assert status=='done';report={'status':'pass','run':'ea18ec6c-3611-452b-bd03-fb4a9ec3edee','source':source,'independent_fullOOF_LP_max_objective_error':max(errors),'coefficients_convex':True,'candidate_checks':checks,'lambda0_numeric_error':zero['numeric_operator_max_abs_error'],'lambda0_control_byte_sha256':best,'source_incumbent_unchanged':True,'exact750_ID_SMILES_order':True,'no_candidate_score_known':True,'not_approved_for_public_dispatch':True,'verification_source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()};(p/'VERIFICATION.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
